  ('mission-w18-01', 'world-18', 'campaign-18a', 'operation-18a-1', 'broken-marketplace', 'The Broken Marketplace', 'The API key recovered from the replica surfaces on Nexus Market, a training clone of a breached commerce platform -- along with a trail of suspicious account activity.', 'intro', ARRAY['ava', 'byte'], '{"requiredMissionIds":["mission-w17-06"]}'::jsonb, null, '{"type":"none"}'::jsonb, '{"xp":60,"credits":10}'::jsonb, false, 1),
